// ---------------------------------------------------------------------------
// Verify signature, validate payload, and shape the Airtable records.
//
// n8n webhooks are unauthenticated by default. The funnel API signs every body
// with SHA-256 over `${body}.${secret}` and sends it as X-Funnel-Signature, so
// knowing the URL is not enough to inject leads into the CRM.
//
// Hosted n8n usually blocks $env (N8N_BLOCK_ENV_ACCESS_IN_NODE=true), and
// touching it then throws. In that case paste the values into the FALLBACK
// constants below instead.
// ---------------------------------------------------------------------------
const FALLBACK_WEBHOOK_SECRET = '';
const FALLBACK_AIRTABLE_BASE_ID = '';

function readEnv(key, fallback) {
  try {
    return $env[key] || fallback;
  } catch (err) {
    return fallback;
  }
}

const crypto = require('crypto');

const item = $input.first();
const body = item.json.body ?? item.json;
const headers = item.json.headers ?? {};
const secret = readEnv('N8N_FUNNEL_WEBHOOK_SECRET', FALLBACK_WEBHOOK_SECRET);
const airtableBaseId = readEnv('AIRTABLE_BASE_ID', FALLBACK_AIRTABLE_BASE_ID);

if (secret) {
  const raw = typeof item.json.rawBody === 'string'
    ? item.json.rawBody
    : JSON.stringify(body);
  const expected = crypto.createHash('sha256').update(`${raw}.${secret}`, 'utf8').digest('hex');
  const provided = headers['x-funnel-signature'] || '';

  const a = Buffer.from(String(provided));
  const b = Buffer.from(expected);
  const valid = a.length === b.length && crypto.timingSafeEqual(a, b);

  if (!valid) {
    return [{ json: { ok: false, statusCode: 401, message: 'Invalid signature' } }];
  }
}

// Schema guard. The workflow is edited in a GUI by people who may not be
// reading the API repo, so an unexpected shape must fail loudly rather than
// writing empty columns into the CRM.
const SUPPORTED_SCHEMA_VERSION = 1;

if (body.schema_version !== SUPPORTED_SCHEMA_VERSION) {
  return [{ json: { ok: false, statusCode: 400, message: `Unsupported schema_version ${body.schema_version}` } }];
}

const required = ['lead_id', 'event_id', 'created_at', 'funnel_version'];
const missing = required.filter((key) => !body[key]);

if (missing.length > 0 || !body.lead || !body.lead.email) {
  return [{ json: { ok: false, statusCode: 400, message: `Payload failed validation: ${missing.join(', ')}` } }];
}

if (!airtableBaseId) {
  return [{ json: { ok: false, statusCode: 500, message: 'AIRTABLE_BASE_ID is not configured' } }];
}

// Map the API's vocabulary onto the base's single-select options. Unknown
// values fall back to 'New' rather than creating stray options via typecast.
const STATUS = {
  new: 'New',
  qualified: 'Qualified',
  review: 'In Progress',
  disqualified: 'Disqualified',
  duplicate: 'New',
};

const lead = body.lead;
const attribution = body.attribution || {};
const score = Number(lead.qualification_score) || 0;
const priority = score >= 70 ? 'High' : score >= 40 ? 'Medium' : 'Low';

// The base has no columns for outcome, reasons or referrer, so they go into
// notes. Reasons are internal only - this base must never feed an ad platform.
const notes = [
  `Outcome: ${lead.qualification_outcome}`,
  `Reasons: ${(lead.qualification_reasons || []).join(', ') || 'none'}`,
  lead.lead_status === 'duplicate' ? 'Repeat submission from a known person.' : null,
  attribution.referrer ? `Referrer: ${attribution.referrer}` : null,
].filter(Boolean).join('\n');

// Fields refreshed on every delivery, including replays.
const updateFields = {
  lead_status: STATUS[lead.lead_status] || 'New',
  lead_priority: priority,
  qualification_score: score,
  notes,
};

const leadFields = {
  funnel_lead_id: body.lead_id,
  conversion_event_id: body.event_id,
  first_name: lead.first_name || '',
  last_name: lead.last_name || '',
  email: lead.email,
  phone: lead.phone || '',
  funnel_version: body.funnel_version,
  source: attribution.source || 'direct',
  medium: attribution.medium || '',
  campaign: attribution.campaign || '',
  content: attribution.content || '',
  term: attribution.term || '',
  fbclid: attribution.fbclid || '',
  landing_page: attribution.landing_page || '',
  ...updateFields,
};

return [{
  json: {
    ok: true,
    payload: body,
    airtable_base_id: airtableBaseId,
    lead_fields: leadFields,
    update_fields: updateFields,
  },
}];

return [{
  json: {
    lead_id: [$('Update Existing Lead').first().json.id],
    workflow: 'lead_to_airtable/duplicate',
    status: 'Success',
    retry_count: 0,
    last_attempt: new Date().toISOString(),
  },
}];

// One Airtable row per answered question (EAV shape). Adding a question to the
// funnel needs no schema change here. lead_id is a link field, so it takes the
// Leads record id rather than the funnel's ld_ id.
const recordId = $('Create Lead').first().json.id;
const answers = $('Verify & Validate').first().json.payload.qualification || [];

return answers.map((row) => ({
  json: {
    lead_id: [recordId],
    question_id: row.question_id,
    answer: row.answer,
    timestamp: row.timestamp,
  },
}));

return [{
  json: {
    lead_id: [$('Create Lead').first().json.id],
    workflow: 'lead_to_airtable',
    status: 'Success',
    retry_count: 0,
    last_attempt: new Date().toISOString(),
  },
}];
